export interface CliProviderModule {
    type: string;
    name: string;
    category: 'cli';
    binary: string;
    /** Manifest version of the loaded spec, carried purely for diagnostics.
     *  A daemon resolves providers from the content-addressed channel store, so
     *  the repo checkout and ~/.adhdev/providers/.upstream can both show a fix
     *  the running daemon does not have (the store pin only advances on
     *  check_provider_updates). Logging this next to the spawn argv is what
     *  distinguishes "our arg expansion is wrong" from "this machine is pinned
     *  to an older spec" without another diagnostic round-trip. */
    providerVersion?: string;
    approvalKeys?: Record<number, string>;
    sendDelayMs?: number;
    /** Wall-clock budget (ms) for a single provider script invocation. Default 50. Range 1..5000.
     *  Exceeding the budget records `timedOut: true` on the invocation trace and emits a
     *  throttled WARN — it does NOT abort the script (Node CJS can't interrupt sync code). */
    scriptCallBudgetMs?: number;
    sendKey?: string;
    submitStrategy?: 'wait_for_echo' | 'immediate';
    /** Require the typed prompt to be visible on the PTY screen before sending Enter. */
    requirePromptEchoBeforeSubmit?: boolean;
    /** When true, only transition to idle after the parsed transcript includes a final standard assistant message.
     *  Also selects the completion-timing FLOOR (mid-tool-valley-prone native source, e.g. codex/kimi/cursor/opencode):
     *  an idle-without-final-assistant holds the decoupled CANON-C completion under the min-elapsed floor. False = a
     *  write-lag native source (e.g. claude-cli) that emits immediately. See holdCompletionForTranscript for the
     *  third (hold) class. */
    requiresFinalAssistantBeforeIdle?: boolean;
    /** Completion-timing HOLD class (e.g. antigravity-cli): a native-history provider whose live idle verdict is
     *  PTY-derived but whose authoritative answer lands in native history. When true, an idle-without-final-assistant
     *  HOLDS for the transcript to land (holdForTranscript) instead of emitting/flooring, and keeps holding past the
     *  30s finalization cap while the PTY is still active (bounded by the hard cap). The third completion-timing class
     *  alongside immediate (requiresFinalAssistantBeforeIdle=false) and floor (requiresFinalAssistantBeforeIdle=true). */
    holdCompletionForTranscript?: boolean;
    /** When true, allow providers to augment stale snapshot data before parse. Reserved for future use. */
    augmentStaleSnapshot?: boolean;
    /** When provider-owned, daemon treats provider parser output as canonical transcript authority. */
    transcriptAuthority?: 'provider' | 'daemon';
    /** Full context lets provider-owned parsers canonicalize retained history instead of daemon prefix stitching. */
    transcriptContext?: 'full' | 'tail';
    /** v1 declarative tui block — used by CliScriptRunner to synthesize SDK helpers (declarativeDetectStatus, declarativeParseApproval). */
    tui?: Record<string, unknown>;
    scripts?: CliScripts;
    spawn: {
        command: string;
        args: string[];
        shell: boolean;
        env: Record<string, string>;
    };
    timeouts?: {
        ptyFlush?: number;
        dialogAccept?: number;
        approvalCooldown?: number;
        generatingIdle?: number;
        idleFinish?: number;
        idleFinishConfirm?: number;
        statusActivityHold?: number;
        maxResponse?: number;
        shutdownGrace?: number;
        outputSettle?: number;
    };
    resume?: ProviderResumeCapability;
    _resolvedVersion?: string | null;
    _resolvedOs?: string | null;
    _resolvedProviderDir?: string | null;
    _resolvedScriptDir?: string | null;
    _resolvedScriptsPath?: string | null;
    _resolvedScriptsSource?: string | null;
    _versionWarning?: string | null;
}

/**
 * PURE-PTY TRANSCRIPT CLASS predicate (kimi and kin).
 *
 * A provider is "pure-PTY full-buffer" when it reconstructs its ENTIRE transcript
 * from the rendered PTY buffer on every read and has NO alternate transcript
 * source:
 *   - transcriptAuthority !== 'provider'  (the daemon PTY parser owns the transcript,
 *     not a provider-side canonical source)
 *   - NO nativeHistory              (no on-disk / native-source history to fall back to)
 *   - tui.transcriptPty.scope === 'buffer' (the parser walks the full rendered buffer)
 *
 * This class is invisible to two provider-authority-keyed code paths that other
 * providers rely on for mesh completion semantics:
 *   1. CliStateEngine.onTurnStarted only promotes to 'generating' for
 *      transcriptAuthority==='provider' providers — so a pure-PTY session that
 *      submits a prompt while already idle collapses idle→idle, the
 *      generating→idle edge never occurs, and agent:generating_completed is never
 *      emitted (the coordinator ledger leaves the task 'assigned' forever).
 *   2. checkMeshWorkerStall's native-transcript completion reconcile is gated on
 *      the native-source shape, so a finished pure-PTY worker's static idle is
 *      misread as monitor:no_progress (a false task_stalled).
 *
 * The runtime capability, NOT any single spec field value, is authoritative: a
 * given kimi manifest checkout may declare nativeHistory/transcriptAuthority, but
 * the live-loaded pure-PTY session has none. Callers that only hold a
 * CliProviderModule (the engine) share this exact predicate with the adapter
 * (parsesFullPtyTranscriptFromBuffer) so the two never drift.
 */
export function isPurePtyTranscriptProvider(provider: {
    transcriptAuthority?: 'provider' | 'daemon';
    nativeHistory?: unknown;
    tui?: Record<string, unknown>;
} | null | undefined): boolean {
    // No provider (e.g. an instance whose module isn't set when the stall watchdog
    // ticks) ⇒ not the pure-PTY class. Guarding here protects every caller — the
    // stall-reconcile and turn-start paths pass this.provider unguarded, and
    // this.provider is genuinely nullable at runtime (see this.provider?.nativeHistory
    // in cli-provider-instance.ts). Matches resolveLocalSessionPurePty's own
    // no-provider ⇒ not-pure-PTY contract.
    if (!provider) return false;
    if (provider.transcriptAuthority === 'provider') return false;
    // nativeHistory is a top-level provider field not surfaced on
    // CliProviderModule; read it via the same structural shape the adapter uses.
    if (provider.nativeHistory) return false;
    const transcriptPty = (provider.tui as { transcriptPty?: { scope?: unknown } } | undefined)?.transcriptPty;
    return transcriptPty?.scope === 'buffer';
}

// OSC and DCS/SOS/PM/APC fuse into one pass: both match non-`ESC[` prefixes and
// both delete their whole match, so a single left-to-right scan is exact.
// eslint-disable-next-line no-control-regex
const ANSI_OSC_DCS_RE = /\x1B\][^\x07]*(?:\x07|\x1B\\)|\x1B[P^_X][\s\S]*?(?:\x07|\x1B\\)/g;
// eslint-disable-next-line no-control-regex
const ANSI_CSI_RE = /\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])/g;

/**
 * Strip ANSI escape sequences.
 *
 * Byte-for-byte identical to the previous three-pass chain; only the pass
 * structure changed. Two rules govern why it is not fused further:
 *
 *  1. The CSI/2-char pass must stay LAST and SEPARATE. Deleting an OSC/DCS can
 *     leave a dangling `ESC[` newly adjacent to following text, and only a
 *     fresh scan will then match it. A fused alternation advances past that
 *     position and never revisits it. (The equivalence suite's fuzz corpus
 *     covers this; fusing the two regexes below turns it red.)
 *  2. The leading indexOf skips the regex engine entirely for plain text,
 *     which is the common case for transcript lines.
 */
// Exported for the equivalence regression suite
// (test/cli/strip-ansi-equivalence.test.ts), which diffs it against a frozen
// copy of the original pass chain. Not part of the module's public surface.
export function stripAnsi(str: string): string {
    if (str.indexOf('\x1B') === -1) return str;
    return str.replace(ANSI_OSC_DCS_RE, '').replace(ANSI_CSI_RE, '');
}

type SavedCursor = { row: number; col: number };

function parseCount(params: string, fallback = 1): number {
    const first = Number(String(params || '').split(';')[0] || fallback);
    return Math.max(1, Number.isFinite(first) ? first : fallback);
}

function isCombiningMark(ch: string): boolean {
    return /[\u0300-\u036F\u1AB0-\u1AFF\u1DC0-\u1DFF\u20D0-\u20FF\uFE20-\uFE2F]/.test(ch);
}

function isWideCodePoint(ch: string): boolean {
    const cp = ch.codePointAt(0) || 0;
    return cp >= 0x1100 && (
        cp <= 0x115F || cp === 0x2329 || cp === 0x232A ||
        (cp >= 0x2E80 && cp <= 0xA4CF && cp !== 0x303F) ||
        (cp >= 0xAC00 && cp <= 0xD7A3) ||
        (cp >= 0xF900 && cp <= 0xFAFF) ||
        (cp >= 0xFE10 && cp <= 0xFE19) ||
        (cp >= 0xFE30 && cp <= 0xFE6F) ||
        (cp >= 0xFF00 && cp <= 0xFF60) ||
        (cp >= 0xFFE0 && cp <= 0xFFE6) ||
        (cp >= 0x1F300 && cp <= 0x1FAFF)
    );
}

/**
 * Stateful, transcript-oriented terminal cell accumulator.
 *
 * CLI transcript parsing must not consume raw PTY append text for user-visible
 * readback: CLIs rewrite prompts/status/tool lines with CR, BS, CSI cursor
 * motion and erase-line. This accumulator preserves parser state across chunks
 * and mutates rendered cells before exposing plain transcript text. It is a
 * deliberately small terminal model for readback buffers; live UI rendering still
 * uses TerminalScreen's ghostty/xterm backend.
 */
export class TerminalTranscriptAccumulator {
    private lines: string[][] = [[]];
    private row = 0;
    private col = 0;
    private savedCursor: SavedCursor | null = null;
    private pendingEscape = '';

    append(data: string): string {
        const input = this.pendingEscape + String(data || '');
        this.pendingEscape = '';
        for (let i = 0; i < input.length; i += 1) {
            let ch = input[i];
            if (ch === '\x1B') {
                const consumed = this.consumeEscape(input.slice(i));
                if (consumed === 0) {
                    this.pendingEscape = input.slice(i);
                    break;
                }
                i += consumed - 1;
                continue;
            }
            const cp = input.codePointAt(i);
            if (cp && cp > 0xFFFF) {
                ch = String.fromCodePoint(cp);
                i += 1;
            }
            this.writeControlOrChar(ch);
        }
        return this.getText();
    }

    reset(): void {
        this.lines = [[]];
        this.row = 0;
        this.col = 0;
        this.savedCursor = null;
        this.pendingEscape = '';
    }

    getText(): string {
        return this.lines.map(line => line.join('').replace(/[ \t]+$/g, '')).join('\n');
    }

    private ensureRow(row = this.row): void {
        while (this.lines.length <= row) this.lines.push([]);
    }

    private writeControlOrChar(ch: string): void {
        if (ch === '\r') {
            this.col = 0;
            return;
        }
        if (ch === '\n') {
            this.row += 1;
            this.col = 0;
            this.ensureRow();
            return;
        }
        if (ch === '\b') {
            this.col = Math.max(0, this.col - 1);
            return;
        }
        if (ch < ' ' || ch === '\x7F') return;

        this.ensureRow();
        const line = this.lines[this.row];
        if (isCombiningMark(ch) && this.col > 0) {
            line[this.col - 1] = `${line[this.col - 1] || ''}${ch}`;
            return;
        }
        while (line.length < this.col) line.push(' ');
        const wide = isWideCodePoint(ch);
        line[this.col] = ch;
        if (wide) line[this.col + 1] = '';
        this.col += wide ? 2 : 1;
    }

    private consumeEscape(seq: string): number {
        if (seq.length < 2) return 0;
        const next = seq[1];
        if (next === '7') {
            this.savedCursor = { row: this.row, col: this.col };
            return 2;
        }
        if (next === '8') {
            if (this.savedCursor) {
                this.row = this.savedCursor.row;
                this.col = this.savedCursor.col;
                this.ensureRow();
            }
            return 2;
        }
        if (next === ']') {
            const bel = seq.indexOf('\x07', 2);
            const st = seq.indexOf('\x1B\\', 2);
            const end = bel >= 0 && (st < 0 || bel < st) ? bel + 1 : st >= 0 ? st + 2 : 0;
            return end;
        }
        if (next === '[') {
            const match = seq.match(/^\x1B\[([0-?]*)([ -/]*)([@-~])/);
            if (!match) return seq.length < 32 ? 0 : 1;
            this.applyCsi(match[1] || '', match[3]);
            return match[0].length;
        }
        if (/[P^_X]/.test(next)) {
            const bel = seq.indexOf('\x07', 2);
            const st = seq.indexOf('\x1B\\', 2);
            const end = bel >= 0 && (st < 0 || bel < st) ? bel + 1 : st >= 0 ? st + 2 : 0;
            return end;
        }
        return 2;
    }

    private applyCsi(params: string, final: string): void {
        const count = parseCount(params);
        this.ensureRow();
        if (final === 'A') this.row = Math.max(0, this.row - count);
        else if (final === 'B') this.row += count;
        else if (final === 'C') {
            // (fix) Cursor-forward must materialize spaces in the cells it
            // skips, otherwise rendered transcripts collapse "Do you" written
            // as "Do\x1b[1Cyou" into "Doyou". That mis-rendering broke
            // Claude Code's approval-prompt and prompt-line detection
            // (parseApproval saw "Doyouwanttoproceed?" and returned null).
            const line = this.lines[this.row];
            for (let c = this.col; c < this.col + count; c += 1) {
                if (line[c] === undefined) line[c] = ' ';
            }
            this.col += count;
        }
        else if (final === 'D') this.col = Math.max(0, this.col - count);
        else if (final === 'G') this.col = Math.max(0, count - 1);
        else if (final === 'H' || final === 'f') {
            const parts = String(params || '').split(';');
            this.row = Math.max(0, (Number(parts[0] || 1) || 1) - 1);
            this.col = Math.max(0, (Number(parts[1] || 1) || 1) - 1);
        } else if (final === 'J') {
            const mode = Number(params || 0) || 0;
            if (mode === 2 || mode === 3) {
                this.lines = [[]];
                this.row = 0;
                this.col = 0;
            } else if (mode === 0) {
                this.lines[this.row] = this.lines[this.row].slice(0, this.col);
                this.lines.splice(this.row + 1);
            } else if (mode === 1) {
                for (let r = 0; r < this.row; r += 1) this.lines[r] = [];
                const line = this.lines[this.row];
                for (let c = 0; c <= Math.min(this.col, line.length - 1); c += 1) line[c] = ' ';
            }
        } else if (final === 'K') {
            const mode = Number(params || 0) || 0;
            const line = this.lines[this.row];
            if (mode === 2) this.lines[this.row] = [];
            else if (mode === 1) {
                for (let c = 0; c <= Math.min(this.col, line.length - 1); c += 1) line[c] = ' ';
            } else {
                this.lines[this.row] = line.slice(0, this.col);
            }
        } else if (final === 's') {
            this.savedCursor = { row: this.row, col: this.col };
        } else if (final === 'u') {
            if (this.savedCursor) {
                this.row = this.savedCursor.row;
                this.col = this.savedCursor.col;
            }
        }
        this.ensureRow();
    }
}

/**
 * Collapse terminal noise into readable text.
 *
 * Deliberately left as FOUR sequential passes. They form a rewrite pipeline in
 * which every stage feeds the next, so no two of them can be fused into one
 * alternation without changing output:
 *   - stage 1 deletes control chars, which can make two previously-separated
 *     \r runs ADJACENT so stage 2 collapses them to a single \n
 *     ("\r\x00\r" -> "\n", fused -> "\n\n");
 *   - stage 3 deletes the "[ \t]+" between two \n runs, JOINING them into one
 *     run that stage 4 then caps at three.
 * Correctness outranks the pass count here; this helper also runs on
 * already-ANSI-stripped (hence short) input, so it is not the hot path. The
 * win in this file comes from stripAnsi above.
 */
function stripTerminalNoise(str: string): string {
    return String(str || '')
        .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, '')
        .replace(/\r+/g, '\n')
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n{4,}/g, '\n\n\n');
}

export function sanitizeTerminalText(str: string): string {
    const accumulator = new TerminalTranscriptAccumulator();
    return stripTerminalNoise(stripAnsi(accumulator.append(str)));
}

// ─── MESH-SEND-KEYS (feature 3: key injection) ─────────────────────────────
//
// The coordinator injects a STRUCTURED key sequence into a worker PTY — never
// raw/base64 bytes (auditability + safety). Each item is either literal UTF-8
// `text` or a named `key` from this closed enum; the encoder maps each key to its
// exact terminal byte sequence. Keeping raw bytes out of the input surface means
// the ledger can record the key ENUM (not the body text) and the destructive-key
// gate can reason about a small, known set.

/** Named PTY keys the send-keys tool accepts (closed enum). */
export type MeshSendKeyName =
    | 'ENTER' | 'ESC' | 'CTRL_C'
    | 'UP' | 'DOWN' | 'LEFT' | 'RIGHT'
    | 'TAB' | 'BACKSPACE';

/** Exact terminal byte sequence for each named key. */
export const MESH_SEND_KEY_ENCODING: Record<MeshSendKeyName, string> = {
    ENTER: '\r',
    ESC: '\x1b',
    CTRL_C: '\x03',
    UP: '\x1b[A',
    DOWN: '\x1b[B',
    RIGHT: '\x1b[C',
    LEFT: '\x1b[D',
    TAB: '\t',
    BACKSPACE: '\x7f',
};

// Destructive keys: they can kill or derail the worker process. CTRL_C sends
// SIGINT (kills the running command / the agent's turn); ESC dismisses / cancels
// modals and pickers. delegatedWorkerAutoApprove is a TOOL-CONSENT policy, NOT a
// PTY-input authorization — so these MUST NOT ride the auto-approve pathway; they
// require an explicit confirm + mesh-policy opt-in. Text / ENTER / arrows / TAB /
// BACKSPACE are non-destructive and need no confirm.
export const MESH_DESTRUCTIVE_KEYS: ReadonlySet<MeshSendKeyName> = new Set<MeshSendKeyName>(['CTRL_C', 'ESC']);

export type MeshSendKeyItem = { text: string } | { key: MeshSendKeyName };

export interface MeshSendKeysEncodeResult {
    /** The concatenated byte sequence to write to the PTY (single atomic write). */
    sequence: string;
    /** Named keys present, in order (for audit — text bodies are NOT recorded). */
    keys: MeshSendKeyName[];
    /** True if any item is a destructive key (CTRL_C / ESC). */
    hasDestructive: boolean;
    /** True if the sequence submits (ends with an ENTER/CR) — informational. */
    submits: boolean;
}

/** Per-call limits (auditability + safety — no unbounded blast). */
export const MESH_SEND_KEYS_MAX_ITEMS = 64;
export const MESH_SEND_KEYS_MAX_TEXT_BYTES = 4096;

/**
 * Validate + encode a structured key sequence into the exact bytes to write.
 * Throws on an invalid key name, an over-limit item count, or an over-limit
 * total text byte length. text+ENTER (or any text followed by ENTER) is encoded
 * as ONE contiguous string so the caller can submit it in a single atomic write
 * — no interleaving between the text and its submit key.
 */
export function encodeMeshSendKeys(items: MeshSendKeyItem[]): MeshSendKeysEncodeResult {
    if (!Array.isArray(items) || items.length === 0) {
        throw new Error('send_keys: sequence must be a non-empty array');
    }
    if (items.length > MESH_SEND_KEYS_MAX_ITEMS) {
        throw new Error(`send_keys: sequence exceeds ${MESH_SEND_KEYS_MAX_ITEMS} items`);
    }
    const parts: string[] = [];
    const keys: MeshSendKeyName[] = [];
    let hasDestructive = false;
    let submits = false;
    let textBytes = 0;
    for (const item of items) {
        if (item && typeof (item as { text?: unknown }).text === 'string') {
            const text = (item as { text: string }).text;
            textBytes += Buffer.byteLength(text, 'utf8');
            if (textBytes > MESH_SEND_KEYS_MAX_TEXT_BYTES) {
                throw new Error(`send_keys: total literal text exceeds ${MESH_SEND_KEYS_MAX_TEXT_BYTES} bytes`);
            }
            parts.push(text);
            submits = false; // literal text after a submit re-opens the line
            continue;
        }
        const keyName = item && typeof (item as { key?: unknown }).key === 'string'
            ? (item as { key: string }).key
            : '';
        if (!(keyName in MESH_SEND_KEY_ENCODING)) {
            throw new Error(`send_keys: unknown key '${keyName}'`);
        }
        const key = keyName as MeshSendKeyName;
        parts.push(MESH_SEND_KEY_ENCODING[key]);
        keys.push(key);
        if (MESH_DESTRUCTIVE_KEYS.has(key)) hasDestructive = true;
        submits = key === 'ENTER';
    }
    return { sequence: parts.join(''), keys, hasDestructive, submits };
}

/**
 * MESH-READ-TERMINAL (feature 2): result of a byte-bounded, bottom-tail terminal
 * screen truncation. The bound is in BYTES (UTF-8), not characters, because a
 * screen full of multi-byte glyphs can blow past an MCP payload cap even when the
 * character count looks safe. The bottom (tail) of the screen is preserved — the
 * prompt, an active modal and the most recent output all live at the bottom — so
 * a truncated read still shows the coordinator the actionable frame.
 */
export interface ByteTailTruncation {
    text: string;
    truncated: boolean;
    /** UTF-8 byte length of the full input before truncation. */
    originalBytes: number;
    /** UTF-8 byte length of the returned (possibly truncated) text. */
    returnedBytes: number;
}

/**
 * Truncate `text` to at most `maxBytes` UTF-8 bytes, preserving whole lines from
 * the BOTTOM up (the prompt/modal/recent output). Never splits a line and never
 * splits a UTF-8 code point (whole-line granularity guarantees valid UTF-8). If
 * even the single last line exceeds the bound, that line is hard-clipped on a
 * safe UTF-8 boundary from its END so the tail is still returned intact-ish.
 */
export function truncateToByteTailByLine(text: string, maxBytes: number): ByteTailTruncation {
    const input = String(text ?? '');
    const originalBytes = Buffer.byteLength(input, 'utf8');
    if (originalBytes <= maxBytes) {
        return { text: input, truncated: false, originalBytes, returnedBytes: originalBytes };
    }
    // Split on newlines, keeping the newline characters so reassembly is exact.
    const lines = input.split('\n');
    const kept: string[] = [];
    let bytes = 0;
    // Walk from the last line upward, adding lines while they fit. Account for the
    // '\n' rejoin cost (1 byte) between kept lines.
    for (let i = lines.length - 1; i >= 0; i--) {
        const line = lines[i];
        const lineBytes = Buffer.byteLength(line, 'utf8');
        const joinCost = kept.length > 0 ? 1 : 0;
        if (bytes + lineBytes + joinCost > maxBytes) break;
        bytes += lineBytes + joinCost;
        kept.unshift(line);
    }
    if (kept.length > 0) {
        const out = kept.join('\n');
        return {
            text: out,
            truncated: true,
            originalBytes,
            returnedBytes: Buffer.byteLength(out, 'utf8'),
        };
    }
    // Degenerate case: the single last line alone exceeds maxBytes. Hard-clip its
    // TAIL on a UTF-8 code-point boundary (Buffer slice can split a multi-byte
    // sequence, so decode-and-recut with the replacement-char guard).
    const lastLine = lines[lines.length - 1] ?? '';
    const buf = Buffer.from(lastLine, 'utf8');
    let slice = buf.subarray(Math.max(0, buf.length - maxBytes));
    // Trim leading bytes until the decode has no leading replacement char (i.e. we
    // landed on a valid code-point boundary).
    let decoded = slice.toString('utf8');
    while (decoded.length > 0 && decoded.charCodeAt(0) === 0xfffd && slice.length > 0) {
        slice = slice.subarray(1);
        decoded = slice.toString('utf8');
    }
    return {
        text: decoded,
        truncated: true,
        originalBytes,
        returnedBytes: Buffer.byteLength(decoded, 'utf8'),
    };
}

export function listCliScriptNames(scripts: CliScripts | undefined): string[] {
    if (!scripts) return [];
    return Object.entries(scripts)
        .filter(([, fn]) => typeof fn === 'function')
        .map(([name]) => name);
}

function splitCliScreenLines(text: string): string[] {
    return String(text || '')
        .replace(/\u0007/g, '')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .split('\n')
        .map((line) => line.replace(/\s+$/, ''));
}

function isPromptLikeCliLine(line: string): boolean {
    const trimmed = String(line || '').trim();
    if (!trimmed) return false;
    return /^[❯›>]\s*(?:$|\S.*)$/.test(trimmed);
}

export function buildCliScreenSnapshot(text: string): CliScreenSnapshot {
    const normalizedText = String(text || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    const rawLines = splitCliScreenLines(normalizedText);
    const lines = rawLines.map((line, index, arr) => {
        const trimmed = String(line || '').trim();
        return {
            index,
            fromTop: index,
            fromBottom: arr.length - index - 1,
            text: line,
            trimmed,
            isEmpty: trimmed.length === 0,
        };
    });
    const nonEmptyLines = lines.filter((line) => !line.isEmpty);
    const firstNonEmptyLine = nonEmptyLines[0] ?? null;
    const lastNonEmptyLine = nonEmptyLines[nonEmptyLines.length - 1] ?? null;
    let promptLineIndex = -1;
    for (let i = lines.length - 1; i >= 0; i -= 1) {
        if (isPromptLikeCliLine(lines[i].text)) {
            promptLineIndex = i;
            break;
        }
    }
    return {
        text: normalizedText,
        lineCount: lines.length,
        lines,
        nonEmptyLines,
        firstNonEmptyLineIndex: firstNonEmptyLine?.index ?? -1,
        lastNonEmptyLineIndex: lastNonEmptyLine?.index ?? -1,
        firstNonEmptyLine,
        lastNonEmptyLine,
        promptLineIndex,
        promptLine: promptLineIndex >= 0 ? lines[promptLineIndex] : null,
        linesAbovePrompt: promptLineIndex >= 0 ? lines.slice(0, promptLineIndex) : [...lines],
        linesBelowPrompt: promptLineIndex >= 0 ? lines.slice(promptLineIndex + 1) : [],
    };
}

