export function computeTerminalQueryTail(buffer: string): string {
    const prefixes = ['\x1b[6n', '\x1b[?6n'];
    const maxLength = prefixes.reduce((n, value) => Math.max(n, value.length), 0) - 1;
    const start = Math.max(0, buffer.length - maxLength);
    for (let i = start; i < buffer.length; i++) {
        const suffix = buffer.slice(i);
        if (prefixes.some((pattern) => suffix.length < pattern.length && pattern.startsWith(suffix))) {
            return suffix;
        }
    }
    return '';
}

/**
 * Windows executable extensions to probe, derived from `%PATHEXT%` so we honor
 * whatever the shell would actually resolve (`.exe;.bat;.cmd;.ps1;…`). We add
 * `.ps1` explicitly (npm now ships PowerShell shims and it is not always in the
 * default PATHEXT) and always include `''` so an already-extensioned name
 * (`codex.cmd`) still matches. Falls back to a sane default list when PATHEXT
 * is unset. Non-win32 callers never reach this.
 */
function windowsExecutableExtensions(): string[] {
    const raw = process.env.PATHEXT;
    const fromEnv = raw
        ? raw.split(';').map((e) => e.trim().toLowerCase()).filter(Boolean)
        : ['.exe', '.cmd', '.bat'];
    const merged = [...fromEnv];
    if (!merged.includes('.ps1')) merged.push('.ps1');
    // Bare name last so extensioned matches win first.
    if (!merged.includes('')) merged.push('');
    // De-dupe while preserving order.
    return Array.from(new Set(merged));
}

/**
 * Best-effort resolution of the active npm global prefix via
 * `npm config get prefix`. This is the authoritative non-default prefix that a
 * daemon's inherited PATH cannot infer — nvm / nvm-windows, `npm config set
 * prefix`, `~/.npm-global`, custom `--prefix`. Consulted with a SHORT timeout so
 * a slow/absent npm never hangs detection, and a successful resolution is
 * memoized per-process so repeated detections don't re-spawn the (relatively
 * slow) npm process. A failed/empty resolution is deliberately NOT cached —
 * only the successful case is expensive+stable enough to be worth freezing;
 * a failure (e.g. system load at boot causing a timeout) must be retried on
 * the next call rather than permanently remembered as "no prefix".
 * Returns the raw prefix dir, or undefined when npm is unavailable.
 */
let cachedNpmPrefix: string | undefined;
function npmGlobalPrefix(): string | undefined {
    if (cachedNpmPrefix !== undefined) return cachedNpmPrefix;
    try {
        const prefix = execSync('npm config get prefix', {
            encoding: 'utf-8',
            timeout: 2000,
            windowsHide: true,
            stdio: ['ignore', 'pipe', 'ignore'],
        }).trim();
        if (prefix && prefix !== 'undefined') cachedNpmPrefix = prefix;
    } catch {
        // npm not on PATH or slow — leave uncached so the next call retries.
    }
    return cachedNpmPrefix;
}

/** Test-only: reset the memoized npm-prefix so a test can re-stub `execSync`. */
export function __resetNpmPrefixCacheForTests(): void {
    cachedNpmPrefix = undefined;
}

/**
 * Common Windows npm-global / package-manager bin dirs that a daemon's inherited
 * PATH frequently misses. Additive and existence-guarded — we only return dirs
 * that exist, so the common path stats nothing extra beyond a handful of paths.
 * `npm config get prefix` is consulted best-effort (short timeout) because it is
 * the authoritative non-default prefix (nvm-windows, custom `--prefix`).
 */
function windowsExtraBinDirs(): string[] {
    const dirs: string[] = [];
    const fs = require('fs');
    const push = (dir: string | undefined | null) => {
        if (!dir) return;
        try { if (fs.existsSync(dir)) dirs.push(dir); } catch { /* best-effort */ }
    };
    if (process.env.APPDATA) push(path.join(process.env.APPDATA, 'npm'));
    if (process.env.LOCALAPPDATA) push(path.join(process.env.LOCALAPPDATA, 'npm'));
    if (process.env.USERPROFILE) push(path.join(process.env.USERPROFILE, 'scoop', 'shims'));
    // nvm-windows / custom prefix: `npm config get prefix` points at the active
    // global bin dir, which on Windows is the prefix dir itself (shims live there).
    push(npmGlobalPrefix());
    try { push(path.dirname(process.execPath)); } catch { /* best-effort */ }
    return dirs;
}

/**
 * Common Unix (Linux/macOS) global-bin dirs that a daemon's minimal non-login
 * PATH frequently misses. The systemd unit ships no PATH pin, so a daemon started
 * outside the user's interactive shell never sees these. Additive and
 * existence-guarded. Notably includes `~/.local/bin`, the Claude Code native
 * installer default (`curl … install.sh | bash`), plus the npm global prefix bin
 * (nvm / `npm config set prefix` / `~/.npm-global`).
 */
function unixExtraBinDirs(): string[] {
    const dirs: string[] = [];
    const fs = require('fs');
    const home = os.homedir();
    const push = (dir: string | undefined | null) => {
        if (!dir) return;
        try { if (fs.existsSync(dir)) dirs.push(dir); } catch { /* best-effort */ }
    };
    // Claude Code native-installer default + alternate native location.
    push(path.join(home, '.local', 'bin'));
    push(path.join(home, '.claude', 'local', 'bin'));
    // Historical / explicit npm-global default.
    push(path.join(home, '.npm-global', 'bin'));
    push('/usr/local/bin');
    push('/opt/homebrew/bin');
    // Active npm prefix bin — covers nvm / custom `npm config set prefix`.
    const prefix = npmGlobalPrefix();
    if (prefix) push(path.join(prefix, 'bin'));
    try { push(path.dirname(process.execPath)); } catch { /* best-effort */ }
    return dirs;
}

export function findBinary(name: string): string {
    const trimmed = String(name || '').trim();
    if (!trimmed) return trimmed;
    const expanded = trimmed.startsWith('~')
        ? path.join(os.homedir(), trimmed.slice(1))
        : trimmed;
    if (path.isAbsolute(expanded) || expanded.includes('/') || expanded.includes('\\')) {
        return path.isAbsolute(expanded) ? expanded : path.resolve(expanded);
    }
    const isWin = os.platform() === 'win32';
    const paths = (process.env.PATH || '').split(path.delimiter);
    // Also search well-known global-bin directories that are frequently NOT on
    // the daemon's inherited PATH. A daemon running under one Node install (e.g.
    // nvm) never sees another npm prefix's bin dir — notably npm's Windows
    // default prefix at %APPDATA%\npm, where `npm i -g @openai/codex` lands. We
    // append these after PATH (so explicit PATH entries still win) so that an
    // npm-global CLI resolves to an absolute path; the spawn layer's .cmd-shim
    // handling then launches it correctly regardless of PATH.
    const extraDirs: string[] = [];
    if (isWin) {
        extraDirs.push(...windowsExtraBinDirs());
    } else {
        extraDirs.push(...unixExtraBinDirs());
    }
    const searchDirs = [...paths, ...extraDirs];
    const exes = isWin ? windowsExecutableExtensions() : [''];

    for (const p of searchDirs) {
        if (!p) continue;
        for (const ext of exes) {
            const fullPath = path.join(p, trimmed + ext);
            try {
                const fs = require('fs');
                if (fs.existsSync(fullPath)) {
                    const stat = fs.statSync(fullPath);
                    if (stat.isFile() && (isWin || (stat.mode & 0o111))) {
                        return fullPath;
                    }
                }
            } catch { }
        }
    }
    return isWin ? `${trimmed}.cmd` : trimmed;
}

export function isScriptBinary(binaryPath: string): boolean {
    if (!path.isAbsolute(binaryPath)) return false;
    try {
        const fs = require('fs');
        const resolved = fs.realpathSync(binaryPath);
        const head = Buffer.alloc(8);
        const fd = fs.openSync(resolved, 'r');
        fs.readSync(fd, head, 0, 8, 0);
        fs.closeSync(fd);
        let i = 0;
        if (head[0] === 0xef && head[1] === 0xbb && head[2] === 0xbf) i = 3;
        return head[i] === 0x23 && head[i + 1] === 0x21;
    } catch {
        return false;
    }
}

export function looksLikeMachOOrElf(filePath: string): boolean {
    if (!path.isAbsolute(filePath)) return false;
    try {
        const fs = require('fs');
        const resolved = fs.realpathSync(filePath);
        const buf = Buffer.alloc(8);
        const fd = fs.openSync(resolved, 'r');
        fs.readSync(fd, buf, 0, 8, 0);
        fs.closeSync(fd);
        let i = 0;
        if (buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) i = 3;
        const b = buf.subarray(i);
        if (b.length < 4) return false;
        if (b[0] === 0x7f && b[1] === 0x45 && b[2] === 0x4c && b[3] === 0x46) return true;
        const le = b.readUInt32LE(0);
        const be = b.readUInt32BE(0);
        const magics = [0xfeedface, 0xfeedfacf, 0xcafebabe, 0xbebafeca];
        return magics.some(m => m === le || m === be);
    } catch {
        return false;
    }
}

export function shSingleQuote(arg: string): string {
    if (/^[a-zA-Z0-9@%_+=:,./-]+$/.test(arg)) return arg;
    if (os.platform() === 'win32') {
        return `"${arg.replace(/"/g, '""')}"`;
    }
    return `'${arg.replace(/'/g, `'\\''`)}'`;
}

export function estimatePromptDisplayLines(text: string, cols = 80): number {
    const normalized = String(text || '').replace(/\r/g, '');
    if (!normalized) return 1;
    return normalized
        .split('\n')
        .reduce((sum, line) => sum + Math.max(1, Math.ceil(Math.max(1, line.length) / cols)), 0);
}

export function extractPromptRetrySnippet(text: string): string {
    const lines = String(text || '')
        .replace(/\r/g, '')
        .split('\n')
        .map(line => line.trim())
        .filter(Boolean);
    const candidate = lines[lines.length - 1] || lines[0] || '';
    return candidate.slice(-120);
}

export function normalizePromptText(text: string): string {
    return String(text || '').replace(/\s+/g, ' ').trim();
}

export function compactPromptText(text: string): string {
    return String(text || '').replace(/\s+/g, '').trim();
}

export function promptLikelyVisible(screenText: string, promptSnippet: string): boolean {
    const snippet = normalizePromptText(promptSnippet);
    if (!snippet) return false;

    const normalizedScreen = normalizePromptText(screenText);
    if (normalizedScreen.includes(snippet)) return true;

    const compactScreen = compactPromptText(screenText);
    const compactSnippet = compactPromptText(promptSnippet);
    if (compactSnippet && compactScreen.includes(compactSnippet)) return true;

    const tokens = snippet
        .split(/[^A-Za-z0-9_.:/-]+/)
        .map(token => token.trim())
        .filter(token => token.length >= 4);
    if (tokens.length === 0) return false;

    const required = Math.min(tokens.length, 3);
    const matched = tokens.filter(token =>
        normalizedScreen.includes(token) || compactScreen.includes(compactPromptText(token)),
    ).length;
    return matched >= required;
}

export function normalizeScreenSnapshot(text: string): string {
    return sanitizeTerminalText(String(text || ''))
        .replace(/\s+/g, ' ')
        .trim();
}

const COMMON_COMPARABLE_WRAP_WORDS = new Set([
    'a', 'an', 'and', 'as', 'at', 'but', 'by', 'for', 'from', 'in', 'into', 'is', 'it', 'of', 'on', 'or', 'that', 'the', 'their', 'then', 'this', 'to', 'was', 'with',
]);

function shouldReflowComparableMessageLines(lines: string[]): boolean {
    return Array.isArray(lines)
        && lines.length > 1
        && lines.slice(0, -1).every((line) => String(line || '').trim().length >= 48)
        && !lines.some((line) => /^```/.test(line))
        && !lines.some((line) => /^\|/.test(line))
        && !lines.some((line) => /^\s*(?:[-*+] |\d+\.\s)/.test(line));
}

function joinComparableMessageLines(lines: string[]): string {
    return lines.reduce((acc, line) => {
        const next = String(line || '').trim();
        if (!next) return acc;
        if (!acc) return next;

        if (/[,\d]$/.test(acc) && /^\d/.test(next)) {
            return `${acc}${next}`;
        }

        if (/[A-Za-z]$/.test(acc) && /^\d/.test(next)) {
            return `${acc}${next}`;
        }

        const fragmentMatch = acc.match(/([A-Za-z]{1,4})$/);
        const fragment = fragmentMatch ? fragmentMatch[1].toLowerCase() : '';
        if (/^[a-z]/.test(next) && fragment && !COMMON_COMPARABLE_WRAP_WORDS.has(fragment)) {
            return `${acc}${next}`;
        }

        return `${acc} ${next}`;
    }, '')
        .replace(/\s+([,.;:!?])/g, '$1')
        .replace(/(\d)\s+,/g, '$1,')
        .replace(/\s+/g, ' ')
        .trim();
}

export function normalizeComparableMessageContent(text: string): string {
    const lines = String(text || '')
        .split(/\r\n|\n|\r/g)
        .map((line) => line.trim())
        .filter(Boolean);

    if (lines.length === 0) return '';
    if (shouldReflowComparableMessageLines(lines)) {
        return joinComparableMessageLines(lines);
    }
    return lines.join(' ')
        .replace(/\s+/g, ' ')
        .trim();
}

export function trimPromptEchoPrefix(text: string, promptText?: string | null): string {
    const prompt = normalizeComparableMessageContent(String(promptText || ''));
    if (!prompt) return String(text || '');

    const lines = String(text || '').split(/\r\n|\n|\r/g);
    let dropCount = 0;
    for (let index = 0; index < Math.min(lines.length, 6); index += 1) {
        const fragment = normalizeComparableMessageContent(lines[index].replace(/^[.…]+\s*/, ''));
        if (!fragment) {
            if (dropCount === index) dropCount = index + 1;
            continue;
        }
        const fragmentWordCount = fragment ? fragment.split(/\s+/).filter(Boolean).length : 0;
        const canBePromptEcho = fragment.length >= 16 || fragmentWordCount >= 4;
        if (canBePromptEcho && prompt.includes(fragment)) {
            dropCount = index + 1;
            continue;
        }
        break;
    }

    return lines.slice(dropCount).join('\n').trim();
}

export function getLastUserPromptText(messages: Array<{ role?: string; content?: string }> | null | undefined): string {
    const items = Array.isArray(messages) ? messages : [];
    for (let index = items.length - 1; index >= 0; index -= 1) {
        const message = items[index];
        if (message?.role === 'user' && typeof message.content === 'string' && message.content.trim()) {
            return message.content;
        }
    }
    return '';
}

function parsePatternEntry(x: unknown): RegExp | null {
    if (x instanceof RegExp) return x;
    if (x && typeof x === 'object' && typeof (x as { source?: string }).source === 'string') {
        try {
            const s = x as { source: string; flags?: string };
            return new RegExp(s.source, s.flags || '');
        } catch {
            return null;
        }
    }
    return null;
}

function coercePatternArray(raw: unknown): RegExp[] {
    if (!Array.isArray(raw)) return [];
    return raw.map(parsePatternEntry).filter((r): r is RegExp => r != null);
}

export function normalizeCliProviderForRuntime(raw: unknown): { patterns: { approval: RegExp[] } } {
    const patterns = raw && typeof raw === 'object' ? (raw as { patterns?: unknown }).patterns : undefined;
    return {
        patterns: {
            approval: coercePatternArray(
                patterns && typeof patterns === 'object' ? (patterns as { approval?: unknown }).approval : undefined,
            ),
        },
    };
}
