// SPEC §5.4, §7.7–7.8 — snapshots: lazy at-cut body construction, byte-level
// chunked transfer, and bootstrap adoption (certHash-gated, directive originals
// verified, heads jump to the cut, replay continues via ordinary WANTs).
import { certHashOf, jcs, sha256HexUtf8 } from "./encoding.js";
import { SeqscribeError } from "./errors.js";
import { b64decode, b64encode } from "./subs.js";
const textEnc = new globalThis.TextEncoder();
const textDec = new globalThis.TextDecoder();
export class SnapshotHub {
    deps;
    assemblies = new Map(); // per peerId+topic
    requested = new Set(); // snapshotIds already GETted
    onAdopted = null;
    constructor(deps) {
        this.deps = deps;
    }
    setOnAdopted(fn) {
        this.onAdopted = fn;
    }
    // ---- responder ----
    // Called by serveWant: a WANT below the cut is answered with an OFFER (§7.8).
    // Returns true when the WANT is fully covered by the snapshot path.
    maybeOffer(session, topic, writer, fromSeq) {
        const cert = this.deps.core.getCert(topic);
        if (!cert)
            return false;
        const cover = cert.cut[writer]?.seq ?? 0;
        if (fromSeq > cover)
            return false;
        void this.buildIfStale(topic).then((body) => {
            if (!body || session.state() !== "ready")
                return;
            const offer = {
                t: "SNAPSHOT_OFFER",
                topic,
                snapshotId: sha256HexUtf8(jcs(body)),
                order: body.order,
                cut: body.cut,
                certHash: body.certHash,
            };
            session.sendControl(offer);
        });
        return true;
    }
    handleGet(session, m) {
        const raw = this.deps.store.metaGet(`snapshot:${m.topic}`);
        if (raw === undefined)
            return; // requester's CONTROL_RETRY re-asks after we build
        const snapshotId = sha256HexUtf8(raw);
        if (snapshotId !== m.snapshotId)
            return; // stale id — a fresh WANT re-offers
        const bytes = textEnc.encode(raw);
        const totalHash = sha256HexUtf8(raw);
        const rawBudget = Math.floor((this.deps.constants.MAX_FRAME_BYTES / 2) * 0.75);
        const of = Math.max(1, Math.ceil(bytes.length / rawBudget));
        for (let chunk = 1; chunk <= of; chunk++) {
            const slice = bytes.subarray((chunk - 1) * rawBudget, chunk * rawBudget);
            session.sendData((mid) => ({
                t: "SNAPSHOT",
                mid,
                topic: m.topic,
                snapshotId,
                chunk,
                of,
                data: b64encode(slice),
                totalHash,
            }));
        }
    }
    async buildIfStale(topic) {
        const cert = this.deps.core.getCert(topic);
        if (!cert)
            return null;
        const stored = this.deps.store.metaGet(`snapshot:${topic}`);
        if (stored !== undefined) {
            const body = JSON.parse(stored);
            if (body.generation === cert.generation)
                return body;
        }
        const policy = this.deps.topics.get(topic).policy;
        const directives = this.deps.store
            .directivesForTopic(topic)
            .map((d) => JSON.parse(d));
        const views = [];
        for (const v of this.deps.views.listForTopic(topic)) {
            const at = this.deps.views.stateAt(v.name, cert.order);
            views.push({ name: v.name, version: v.version, state: at.state, stateHash: at.stateHash });
        }
        const body = {
            topic,
            order: cert.order,
            generation: cert.generation,
            certHash: certHashOf(cert),
            cut: cert.cut,
            directives,
            views,
        };
        if (policy.kind === "register")
            body.register = await this.deps.registers.stateAt(topic, cert.order);
        // JCS-canonical storage so snapshotId is reproducible from the stored bytes
        this.deps.store.metaSet(`snapshot:${topic}`, jcs(body));
        return body;
    }
    // ---- requester ----
    handleOffer(session, m) {
        const cert = this.deps.core.getCert(m.topic);
        // a consumer holding NO verified cert MUST NOT adopt (§5.4) — fgen repair first
        if (!cert || certHashOf(cert) !== m.certHash)
            return;
        // skip when the local basis already covers the cut
        let needed = false;
        for (const [writer, cut] of Object.entries(m.cut)) {
            if (this.deps.core.getStream(m.topic, writer).contigSeq < cut.seq) {
                needed = true;
                break;
            }
        }
        if (!needed || this.requested.has(m.snapshotId))
            return;
        this.requested.add(m.snapshotId);
        const wants = this.deps.views.listForTopic(m.topic);
        session.request(`SNAPGET:${m.snapshotId}`, () => ({
            t: "SNAPSHOT_GET",
            topic: m.topic,
            snapshotId: m.snapshotId,
            wants,
        }));
    }
    handleChunk(session, m) {
        const key = `${session.peerId}�${m.topic}`;
        let asm = this.assemblies.get(key);
        if (!asm || asm.snapshotId !== m.snapshotId) {
            asm = { snapshotId: m.snapshotId, of: m.of, chunks: new Map(), bytes: 0, totalHash: null };
            this.assemblies.set(key, asm);
        }
        // MAX_REASSEMBLY_BYTES (proposals-v3.5 P7): `of` is peer-chosen, so chunk
        // indices in [1, of] (parseMsg) don't bound this map. Delta-aware — data-
        // lane ARQ retransmits overwrite, they don't double-count. Overflow is a
        // protocol violation: ERR + close, matching the §5.2 credit-window bound.
        // The snapshotId leaves `requested` again because it is content-derived —
        // an honest peer serving the SAME legitimate body after redial must not be
        // silently ignored just because a hostile stream burned the id.
        asm.bytes += m.data.length - (asm.chunks.get(m.chunk)?.length ?? 0);
        if (asm.bytes > this.deps.constants.MAX_REASSEMBLY_BYTES) {
            this.assemblies.delete(key);
            this.requested.delete(m.snapshotId);
            session.sendControl({
                t: "ERR",
                code: "ERR_ENTRY_ENCODING",
                detail: `SNAPSHOT reassembly exceeds MAX_REASSEMBLY_BYTES (${m.topic})`,
            });
            session.close("protocol");
            return;
        }
        asm.chunks.set(m.chunk, m.data);
        if (m.totalHash !== undefined)
            asm.totalHash = m.totalHash;
        if (asm.chunks.size < asm.of)
            return;
        this.assemblies.delete(key);
        session.satisfyRequest(`SNAPGET:${m.snapshotId}`);
        const parts = [];
        for (let i = 1; i <= asm.of; i++)
            parts.push(b64decode(asm.chunks.get(i) ?? ""));
        const total = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
        let off = 0;
        for (const p of parts) {
            total.set(p, off);
            off += p.length;
        }
        const raw = textDec.decode(total);
        // parse ONLY after all chunks and hash verification (§5.4)
        if (asm.totalHash !== null && sha256HexUtf8(raw) !== asm.totalHash)
            return;
        if (sha256HexUtf8(raw) !== m.snapshotId)
            return; // snapshotId is self-binding
        void this.adopt(JSON.parse(raw));
    }
    async adopt(body) {
        const cert = this.deps.core.getCert(body.topic);
        if (!cert || certHashOf(cert) !== body.certHash)
            return;
        // verify every directive's signature; adopt the highest rgen per writer (§7.7)
        const verify = this.deps.authority?.verifyWriterDirective;
        const byWriter = new Map();
        for (const d of body.directives) {
            if (!verify || !(await verify(d))) {
                this.deps.emitAnomaly({ kind: "bad_directive" });
                return; // a snapshot carrying an unverifiable directive is not adoptable
            }
            const cur = byWriter.get(d.writer);
            if (!cur || d.rgen > cur.rgen)
                byWriter.set(d.writer, d);
        }
        await this.deps.core.adoptSnapshotCut(body.topic, body.cut);
        for (const d of byWriter.values())
            await this.deps.core.applyDirective(d);
        const policy = this.deps.topics.get(body.topic).policy;
        if (policy.kind === "register" && body.register)
            this.deps.registers.installSnapshot(body.topic, body.register, body.order);
        const registered = this.deps.views.listForTopic(body.topic);
        for (const v of registered) {
            const match = body.views.find((bv) => bv.name === v.name && bv.version === v.version);
            if (match) {
                if (sha256HexUtf8(jcs(match.state)) !== match.stateHash)
                    throw new SeqscribeError("ERR_ENTRY_ENCODING", `snapshot view state hash mismatch (${v.name})`);
                this.deps.views.installState(v.name, match.state, body.order);
            }
            else {
                // starts from init at the cut — host must provision full state if
                // completeness is required (§7.8)
                this.deps.views.installState(v.name, undefined, body.order);
                this.deps.views.markBootstrapPartial(v.name);
            }
        }
        this.onAdopted?.(body.topic);
    }
}
